import{_ as l,l as o,o as e,c as s,v as t,p as n,x as r,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"视图与物化","description":"","frontmatter":{"title":"视图与物化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/views-materialize.md","filePath":"cs/views-materialize.md","lastUpdated":1789023840000}'),c={name:"cs/views-materialize.md"};function h(A,a,m,_,u,f){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="视图与物化" tabindex="-1">视图与物化 <a class="header-anchor" href="#视图与物化" aria-label="Permalink to &quot;视图与物化&quot;">​</a></h1><div class="epigraph"><p>视图是命名的查询；虚的每次重算，实的把结果存住，更新则变成维护问题。</p><footer>—— 据 Date 对视图；Gupta and Mumick 对物化视图维护的整理</footer></div><p><a href="/cs/bcnf-3nf">上一课</a>把宽表按依赖切开。本课不重做 3NF 合成。缺口是：用户仍想看见「一张订单宽表」，而基表已经分解。视图把一条声明查询命名成虚拟关系；物化则把结果写成真实存储，用空间换重复求值。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分解之后，每次查询都要连接。若把连接写成应用里的字符串，模式一变，字符串全碎。缺口不是新代数，而是<strong>外模式</strong>：视图的指称是某棵查询树，对用户仍是关系。虚视图不占堆文件；物化视图占存储，基表一改就要维护，否则读到的是过期快照。</p><p>本课不把「可更新视图」的全部定理写完，只钉：读视图 = 求值或读副本；写视图往往没有唯一的基表翻译。</p><p><span class="marginnote">Codd 的三层模式：内模式存储、概念模式基表、外模式视图。数据独立性的用户侧就是这一层，与<a href="/cs/relational-model">关系模型</a>第一课的独立性相接。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>虚视图：打开查询时把视图名换成定义树，再走<a href="/cs/query-rewrite">改写</a>与计划。物化：把结果存成表，选立即维护或延迟刷新。增量维护：基表 delta 推出视图 delta，避免全量重算。本课不展开维护规则的代数，只要求维护保持与定义树一致。</p>',9)),(e(),n(E,null,{default:r(()=>[p(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20BASE%5B%22%E5%9F%BA%E8%A1%A8%22%5D%20--%3E%20VV%5B%22%E8%99%9A%E8%A7%86%E5%9B%BE%3A%20%E5%B1%95%E5%BC%80%E6%A0%91%22%5D%0A%20%20BASE%20--%3E%20MV%5B%22%E7%89%A9%E5%8C%96%3A%20%E5%AD%98%E7%BB%93%E6%9E%9C%22%5D%0A%20%20MV%20--%3E%20MAINT%5B%22%E5%A2%9E%E9%87%8F%20%2F%20%E5%88%B7%E6%96%B0%22%5D%0A%20%20VV%20--%3E%20PAGE%5B%22%E5%90%8E%E8%AF%BE%3A%20%E9%A1%B5%E4%B8%8E%E6%A7%BD%22%5D%0A%20%20MV%20--%3E%20PAGE%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>优化器可以把视图当改写的匹配对象：若物化结果能覆盖当前查询，就改成扫描该副本（视图匹配）。这与索引的角色相近，但是「预计算的查询」而不是「预计算的查找结构」。虚视图则把逻辑树变大，下推仍然适用。</p><p>更新异常在视图上更尖：一张视图行可能对应多张基表上的组合，插入无法唯一分解。因此主干把视图首先当读接口；可更新子集是工程特例。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲流式物化、列存 Cube 的全部 OLAP 栈。也不把缓存失效协议写细。物理上物化结果仍是后课的页与堆文件；本课只决定「有没有这一份关系副本」。</p><p>临时表与 CTE 不是物化视图：它们的寿命是查询或会话，不进入模式的持久外模式。后课默认：用户可以面对视图；存储引擎看到的是基表（及可选的物化副本）上的页。</p><p>外模式可以宽，内模式可以窄。用户看见的名字不必等于堆文件的名字，这是独立性在本课的落点。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分解之后用视图恢复外模式；虚的展开，实的维护。</li><li>读匹配可以省连接；写视图一般没有唯一翻译。</li><li>元组落在哪一页、哪一个槽，是后课缺口。</li><li>出处：Date；Gupta and Mumick；Garcia-Molina, Ullman and Widom。</li></ul>',9))])}const b=l(c,[["render",h]]);export{T as __pageData,b as default};
